#- # model.rb --- one Active Record class per entity.
#- #
#- # The associations, the cascade and the presence validations are all
#- # the model's: `parent`, `children` and each field's `required`.
#- @"../model.aon"
#-
#- out: emit($.entity, {
#-   match: class: string
#-   body: [
#-     file("app/models/" + .id + ".rb", emit([_], {
#-       match: class: string
#-       replace: CLASS: .class
#-       body: [
# Generated by `aontu render` from model.aon. Do not edit.

class CLASS < ApplicationRecord
  # THE CLIENT NAMES THE RECORD. `earth`, `luna`: the primary key is a
  # string the caller supplies, so Active Record is told which column
  # it is rather than looking for an integer counter.
  self.primary_key = "id"
#-         # WHAT HANGS OFF THIS ONE. `dependent: :destroy` is the cascade the
#-         # reference's test 18 reads: delete Jupiter and its moons go with it.
#-         emit(.children, {
#-           match: name: string
#-           replace: { HAS:.name OF:.class ON:.fk }
#-           body: [

  has_many :HAS, class_name: "OF", foreign_key: "ON", dependent: :destroy
#-           ]
#-         })
#-         # WHAT THIS ONE HANGS OFF. An entity with no `parent` key selects
#-         # nothing here and gets no `belongs_to`.
#-         emit(filter([_], { parent:string }), {
#-           match: parent: string
#-           replace: {
#-             PARENTNAME: .parent
#-             PARENTKLASS: .parent_class
#-             FKEY: .parent_param
#-           }
#-           body: [

  belongs_to :PARENTNAME, class_name: "PARENTKLASS", foreign_key: "FKEY"
#-           ]
#-         })
#-         # PRESENCE IS THE MODEL'S `required`. The reference's test 14 posts a
#-         # planet with no `kind` and reads the word `kind` back out of the
#-         # message, so the attribute name has to reach the wire in the case
#-         # the model wrote it.
#-         emit(filter(.field, { required:true }), {
#-           match: name: string
#-           replace: FIELD: .name
#-           body: [
  validates :FIELD, presence: true
#-           ]
#-         })
end
#-       ]
#-     }))
#-   ]
#- })
